from prison import Player
import math

PAYOFF = [[[6, 3], [3, 0]], [[8, 5], [5, 2]]]
WINDOW = 50
MODEL_NAME = 'PrisonerAI500K'


def encode_input(past, window):
    # Turn the match history into the model's input vector
    # past is a list of rounds, each round is (my action, opp1 action, opp2 action).
    rounds_played = len(past)
    recent = past[-window:]
    missing = window - len(recent)

    # Last window rounds of actions padded with zeroes on the left.
    vector = [0] * (3 * missing)
    for row in recent:
        for action in row:
            vector.append(action)

    # 0 for padding 1 for real round mask
    for i in range(missing):
        vector.append(0)
    for i in range(len(recent)):
        vector.append(1)

    # Cooperation rate and current defection streak for every player
    rates = []
    streaks = []
    for seat in range(3):
        cooperations = 0
        for row in past:
            if row[seat] == 0:
                cooperations += 1
        if rounds_played > 0:
            rates.append(cooperations / rounds_played)
        else:
            rates.append(0.0)

        streak = 0
        for row in reversed(past):
            if row[seat] != 1:
                break
            streak += 1
        streaks.append(streak / 100)

    # How often both opponents cooperated or both defected + average payoff
    both_cooperate = 0
    both_defect = 0
    total_payoff = 0
    for row in past:
        if row[1] == 0 and row[2] == 0:
            both_cooperate += 1
        if row[1] == 1 and row[2] == 1:
            both_defect += 1
        total_payoff += PAYOFF[row[0]][row[1]][row[2]]

    if rounds_played > 0:
        both_cooperate_rate = both_cooperate / rounds_played
        both_defect_rate = both_defect / rounds_played
        average_payoff = total_payoff / (8 * rounds_played)
    else:
        both_cooperate_rate = 0.0
        both_defect_rate = 0.0
        average_payoff = 0.0

    summary = [rounds_played / 100] + rates + streaks
    summary += [both_cooperate_rate, both_defect_rate, average_payoff]
    return vector + summary


class PrisonerAI500K(Player):
    def agentName(self):
        return MODEL_NAME

    @staticmethod
    def _dense(x, weights, bias):
        # Fully connected layer output[i] = bias[i] + sum_weights[i][j] * x[j]
        outputs = []
        for i in range(len(weights)):
            total = 0.0
            for j in range(len(x)):
                total += weights[i][j] * x[j]
            outputs.append(bias[i] + total)
        return outputs

    @staticmethod
    def _sigmoid(x):
        if x >= 0:
            return 1.0 / (1.0 + math.exp(-x))
        e = math.exp(x)
        return e / (1.0 + e)

    def _forward(self, x):
        # Run the GRU over the last WINDOW rounds then the dense ReLU layers
        p = PARAMETERS
        size = p['hidden_size']
        hidden = [0.0] * size

        for t in range(WINDOW):
            mask = x[3 * WINDOW + t]
            if not mask:
                continue  # skip padding
            step = [x[3 * t], x[3 * t + 1], x[3 * t + 2], mask]
            gi = self._dense(step, p['weight_ih'], p['bias_ih'])
            gh = self._dense(hidden, p['weight_hh'], p['bias_hh'])

            updated = []
            for j in range(size):
                reset = self._sigmoid(gi[j] + gh[j])
                update = self._sigmoid(gi[size + j] + gh[size + j])
                new = math.tanh(gi[2 * size + j] + reset * gh[2 * size + j])
                updated.append((1 - update) * new + update * hidden[j])
            hidden = updated

        x = hidden + x[-10:]

        # Dense layers with ReLU
        layers = p['layers']
        for i in range(len(layers)):
            x = self._dense(x, layers[i]['weight'], layers[i]['bias'])
            if i < len(layers) - 1:
                for j in range(len(x)):
                    if x[j] < 0.0:
                        x[j] = 0.0
        return x

    def predict(self, x):
        swapped = []
        for i in SWAP_INDEX:
            swapped.append(x[i])

        normal_out = self._forward(x)
        swapped_out = self._forward(swapped)

        # Outputs are [Q_C, Q_D, P_CC, P_CD, P_DC, P_DD]. 
        swapped_position = [0, 1, 2, 4, 3, 5]
        outputs = []
        for i in range(6):
            outputs.append((normal_out[i] + swapped_out[swapped_position[i]]) / 2)
        return outputs

    def play(self, myHistory, oppHistory1, oppHistory2):
        # Defect if the predicted payoff for defecting is higher else cooperate
        past = []
        for i in range(len(myHistory)):
            past.append((myHistory[i], oppHistory1[i], oppHistory2[i]))

        outputs = self.predict(encode_input(past, WINDOW))
        self.last_outputs = outputs
        if outputs[1] <= outputs[0]:
            return 0

        # Never be the first person to defect
        if len(past) > 0 and oppHistory1[-1] == 0 and oppHistory2[-1] == 0:
            return 0
        return 1


