def _swap_index():
    # Positions of the input vector with opponent 1 and opponent 2 exchanged
    index = []

    # History: each round (me, opp1, opp2) becomes (me, opp2, opp1).
    for t in range(WINDOW):
        index.append(3 * t)
        index.append(3 * t + 2)
        index.append(3 * t + 1)

    # Masks stay where they are.
    for i in range(3 * WINDOW, 4 * WINDOW):
        index.append(i)

    # Summary: [rounds, my rate, opp1 rate, opp2 rate, my streak, opp1 streak,
    # opp2 streak, both cooperate, both defect, my payoff]. Swap the opponent pairs.
    s = 4 * WINDOW
    summary_order = [0, 1, 3, 2, 4, 6, 5, 7, 8, 9]
    for i in summary_order:
        index.append(s + i)
    return index


SWAP_INDEX = _swap_index()